  s='<div class="sample-label"><span>PROPOSED · STATIC RECOVERY SAMPLE</span></div><main class="phone-content" data-od-id="companion-recovery"><div class="phone-brand">Virtual Squash / Pocket Racket</div><div class="eyebrow" style="margin-top:24px">Experimental phone controller</div><h1>Reconnect to<br>your court.</h1><p>Keep this phone in your hand. Your match stays on the main screen.</p><div class="phone-state"><strong>Not connected</strong><p>No court has acknowledged this controller. Check that both devices use the same game server and room.</p>'+fake('Reconnect to court','primary')+'</div><div class="keyrow"><span>Room / player</span><b>Not confirmed</b></div><div class="keyrow"><span>Motion sensors</span><b>Not enabled</b></div><p class="hint">Motion is optional. After pairing, you can use touch controls without granting sensor access.</p><div class="shots">'+fake('Drive','disabled')+fake('Drop','disabled')+fake('Boast','disabled')+fake('Lob','disabled')+fake('Kill','disabled')+fake('Call Let','disabled')+'</div><p class="hint">Shot controls become available after acknowledgment. No camera or microphone is needed for touch play.</p></main>'
